from pathlib import Path
p=Path('src/Notes.jsx');s=p.read_text(encoding='utf-8');s=s.replace("AppWindow, Link2 }", "AppWindow, Link2, Sun, Moon, Menu, X, ArrowLeft }");s=s.replace("const [submissionCategory,setSubmissionCategory]=useState('Engineering');", "const [submissionCategory,setSubmissionCategory]=useState('Engineering');\n const [menuOpen,setMenuOpen]=useState(false);\n const resetFilters=()=>{setCategory('All');setTopicFilter('All');setFormatFilter('all');setSearch('');setSort('newest')};")
