a=s.index('<nav className="notes-nav"');b=s.index('</nav>',a)+len('</nav>')
s=s[:a]+'''<nav className="notes-nav" aria-label="Notebook navigation" onKeyDown={e=>{if(e.key==='Escape'){setMenuOpen(false);document.getElementById('notes-menu-toggle')?.focus()}}}><a className="notes-brand" href="/"><span className="notes-brand-mark">AG</span><span>Ayush Gupta<small>THE NOTEBOOK</small></span></a><div className="notes-nav-actions"><button className="notes-theme" type="button" onClick={toggleTheme} aria-label={isDark?'Switch to light theme':'Switch to dark theme'}>{isDark?<Sun size={17} aria-hidden="true"/>:<Moon size={17} aria-hidden="true"/>}<span>{isDark?'Light':'Dark'}</span></button><button className="notes-menu-toggle" id="notes-menu-toggle" type="button" aria-expanded={menuOpen} aria-controls="notes-nav-links" aria-label={menuOpen?'Close navigation':'Open navigation'} onClick={()=>setMenuOpen(v=>!v)}>{menuOpen?<X size={20}/>:<Menu size={20}/>}</button></div><div className={`notes-nav-links ${menuOpen?'is-open':''}`} id="notes-nav-links"><a className="notes-home" href="/"><ArrowLeft size={15} aria-hidden="true"/>Back to portfolio</a><a href="/notes" aria-current="page" onClick={()=>setMenuOpen(false)}>Notebook</a><a className="notes-nav-cta" href="#contribute" onClick={()=>setMenuOpen(false)}>Share a note ↗</a></div><span className="notes-progress" aria-hidden="true"/></nav>'''+s[b:]
s=s.replace('<div className="notes-toolbar"><div aria-label="Filter notes">', '<div className="notes-category-heading"><h2>Explore the notebook</h2><p>Published entries in each category</p></div><div className="notes-toolbar"><div className="notes-category-counts" role="group" aria-label="Filter by category">')
s=s.replace("<button key={c} aria-pressed={category===c}","<button key={c} className=\"notes-category-button\" aria-label={`${c}: ${loading?'loading':categoryCounts[c]} published entries`} aria-pressed={category===c}")
s=s.replace("setTopicFilter('All')}}>{c}</button>","setTopicFilter('All')}}><span>{c==='All'?'All entries':c}</span><strong>{loading?'—':categoryCounts[c]}</strong></button>")
s=s.replace("onClick={()=>{setCategory('All');setTopicFilter('All');setFormatFilter('all');setSearch('');setSort('newest')}}", "onClick={resetFilters}")
s=s.replace('<p className="notes-result-count"', '''{(category!=='All'||topicFilter!=='All'||formatFilter!=='all'||search)&&<div className="notes-active-filters" aria-label="Active filters">{category!=='All'&&<button type="button" onClick={()=>{setCategory('All');setTopicFilter('All')}}>Category: {category} <X size={13} aria-hidden="true"/><span className="notes-sr-only">Remove category filter</span></button>}{topicFilter!=='All'&&<button type="button" onClick={()=>setTopicFilter('All')}>Topic: {topicFilter} <X size={13} aria-hidden="true"/><span className="notes-sr-only">Remove topic filter</span></button>}{formatFilter==='pdf'&&<button type="button" onClick={()=>setFormatFilter('all')}>PDF notes <X size={13} aria-hidden="true"/><span className="notes-sr-only">Remove PDF filter</span></button>}{search&&<button type="button" onClick={()=>setSearch('')}>Search: {search} <X size={13} aria-hidden="true"/><span className="notes-sr-only">Clear search</span></button>}</div>}<p className="notes-result-count"''')
s=s.replace("`${filtered.length} notes to explore`", "`${filtered.length} ${filtered.length===1?'entry':'entries'} shown · ${posts.length} published`")
s=s.replace("Try another topic or search.","Remove a filter or try a different search.")
s=s.replace("Published notes will appear here after review.'}</p></div>","Published notes will appear here after review.'}</p><button type=\"button\" className=\"notes-button\" onClick={resetFilters}>Show all entries</button></div>")
p.write_text(s,encoding='utf-8')
